import{_ as n,l as d,o as a,c as f,v as i,p as r,x as o,d as c,i as l,S as s}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"inotify 与 fanotify","description":"","frontmatter":{"title":"inotify 与 fanotify","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inotify.md","filePath":"cs/inotify.md","lastUpdated":1789023840000}'),h={name:"cs/inotify.md"};function p(y,e,_,m,u,E){const t=d("Mermaid");return a(),f("div",null,[e[1]||(e[1]=i('<h1 id="inotify-与-fanotify" tabindex="-1">inotify 与 fanotify <a class="header-anchor" href="#inotify-与-fanotify" aria-label="Permalink to &quot;inotify 与 fanotify&quot;">​</a></h1><div class="epigraph"><p>inotify 在 inode 上挂监视器，把 create/modify/delete 编成用户可读的事件队列；fanotify 面向整树扫描与访问许可钩子。</p><footer>—— 据 Linux inotify(7)、fanotify(7)；Love, <em>Linux System Programming</em> 对目录事件的整理</footer></div><p><a href="/cs/file-locking">上一课</a>让自愿者互斥。备份、IDE、安全扫描还想<strong>不轮询</strong>地知道树变了。缺口是 inotify：内核在 <a href="/cs/vfs">VFS</a> 操作成功后排队事件。fanotify 是更粗的、可拦截的亲戚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>stat</code> 轮询浪费，且有窗口。inotify：对 fd 或路径加 watch，掩码选 <code>IN_CREATE</code> 等。事件带 name（目录 watch 时）与 cookie（配对 rename）。队列有上限，溢出得 <code>IN_Q_OVERFLOW</code>，之后状态未知必须重扫。缺口：递归必须自己对每个子目录加 watch；不穿越挂载点；与 <a href="/cs/overlayfs">overlay</a> copy-up 的事件可能令人惊讶。fanotify 可对整挂载标记，并可 <code>FAN_ACCESS_PERM</code> 允许/拒绝——那是安全钩，不是 IDE 补全。</p><p><span class="marginnote">递归与「文件还是目录」要应用自己处理。网络 FS 上事件可能丢失或不支持。本课不把 inotify 写成 GUI 框架文档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>inotify_init1</code> 得 fd，<code>inotify_add_watch</code> 把 watch 挂到 inode。VFS <code>mkdir</code>/<code>unlink</code>/<code>write</code> 路径末尾向监视器投递。用户 <code>read</code> 该 fd 得二进制事件。对照 <a href="/cs/fuse">FUSE</a>：用户态 FS 必须自己决定是否生成内核可转发的事件。对照 dcache：watch 的是 inode，名字事件来自目录操作。</p>',8)),(a(),r(s,null,{default:o(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VFSOP%5B%22VFS%20%E6%94%B9%E6%A0%91%22%5D%20--%3E%20W%5B%22inode%20watches%22%5D%0A%20%20W%20--%3E%20Q%5B%22%E4%BA%8B%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20U%5B%22%E7%94%A8%E6%88%B7%20read%20inotify%20fd%22%5D%0A%20%20OV%5B%22%E9%98%9F%E5%88%97%E6%BB%A1%22%5D%20--%3E%20OVER%5B%22IN_Q_OVERFLOW%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>inotify 把「目录是文件」的修改变成可 select/poll 的流，使桌面搜索与同步工具可事件驱动。它不提供事务：事件序列不是 FS 日志的提交切面，崩溃中间仍要以盘为准。不要把事件流写成数据库 CDC。</p><p>fanotify 的许可钩进入 LSM 一类决策点，延迟与拒绝策略属于安全课序，本课只点「能挡」。</p><p>实现上：递归监视要自己对 mkdir 事件加 watch，否则新子树静默。队列溢出后必须全量重扫，不能当事务日志 replay。fanotify 的许可钩会把打开路径变成同步决策点，延迟进关键路径。 读法上只引用<a href="/cs/file-locking">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>inotify 与 fanotify</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>fsnotify</code> 内部扇出到 audit 的全部钩子。不保证 chroot 内外的 watch 可见性故事写完。下一课把「换名」从事件里抽出，专钉 POSIX <code>rename</code> 的原子性。</p><p>版本字段会变，课序钉的是机制对象「inotify 与 fanotify」，不是某一主线内核的结构体名。 后课默认：用户态可订阅 inode 事件，队列会溢。同一目录项换名是否原子可见，下一课 rename。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>inotify 按 inode 排队目录/文件事件；会溢出。</li><li>fanotify 面向挂载级监视与可选许可。</li><li>rename 原子性是下一课。</li><li>出处：Linux <code>inotify(7)</code>、<code>fanotify(7)</code>；Love, <em>LSP</em>。</li></ul>',11))])}const B=n(h,[["render",p]]);export{A as __pageData,B as default};
